TLM.f("Sancti/03-28",{"officium":"S. Joannis a Capistrano Confessoris","rule":["vide C5;","Gloria"],"fallback":"Commune/C5","sections":{"Introitus":[{"k":"ref","la":"Habac 3:18-19"},{"k":"text","la":"Ego autem in Dómino gaudébo: et exsultábo in Deo, Jesu meo: Deus Dóminus fortitúdo mea."},{"k":"ref","la":"Ps 80:2"},{"k":"text","la":"Exsultáte Deo, adjutóri nostro, jubiláte Deo Jacob."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Ego autem in Dómino gaudébo: et exsultábo in Deo, Jesu meo: Deus Dóminus fortitúdo mea."}],"Oratio":[{"k":"text","la":"Deus, qui per beátum Joánnem fidéles tuos in virtúte sanctíssimi nóminis Jesu de Crucis inimícis triumpháre fecísti: præsta, quǽsumus; ut, spirituálium hóstium, ejus intercessióne, superátis insídiis, corónam justítiæ a te accípere mereámur."},{"k":"macro","name":"Per eundem"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Sap 10:10-14"},{"k":"text","la":"Justum dedúxit Dóminus per vias rectas, et ostendit illi regnum Dei, et dedit illi sciéntiam sanctórum: honestávit illum in labóribus, et complévit labores illíus. In fraude circumveniéntium illum áffuit illi, et honéstum fecit illum. Custodívit illum ab inimícis, et a seductóribus tutávit illum, et certámen forte dedit illi, ut vínceret et sciret, quóniam ómnium poténtior est sapiéntia. Hæc vénditum justum non derelíquit, sed a peccatóribus liberávit eum: descendítque cum illo in fóveam, et in vínculis non derelíquit illum, donec afférret illi sceptrum regni, et poténtiam advérsus eos, qui eum deprimébant: et mendáces osténdit, qui maculavérunt illum, et dedit illi claritátem ætérnam, Dóminus, Deus noster."}],"Graduale":[{"k":"ref","la":"Ps 21:24-25"},{"k":"text","la":"Qui timétis Dóminum, laudáte eum: univérsum semen Jacob, glorificáte eum."},{"k":"text","la":"Timeat eum omne semen Israël: quóniam non sprevit, neque despéxit deprecatiónem páuperis.","mark":"V"},{"k":"text","la":"Allelúja, allelúja"},{"k":"ref","la":"Ps 58:17"},{"k":"text","la":"Ego autem cantábo fortitúdinem tuam: et exsultábo mane misericórdiam tuam. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 58:17"},{"k":"text","la":"Ego autem cantábo fortitúdinem tuam: et exsultábo mane misericórdiam tuam. Allelúja,"},{"k":"text","la":"Quia factus es suscéptor meus, et refúgium meum in die tribulatiónis meæ. Allelúja.","mark":"V"}],"Tractus":[{"k":"ref","la":"Ps 21:24-25"},{"k":"text","la":"Qui timétis Dóminum, laudáte eum: univérsum semen Jacob, glorificáte eum."},{"k":"text","la":"Tímeat eum omne semen Israël: quóniam non sprevit, neque despéxit deprecatiónem páuperis.","mark":"V"},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Ex 15:2 et 3"},{"k":"text","la":"Fortitúdo mea et laus mea Dóminus, et factus est mihi in salútem: iste Deus meus, et glorificábo eum."},{"k":"text","la":"Dóminus quasi vir pugnátor, omnípotens nomen ejus.","mark":"V"},{"k":"ref","la":"Judith 16:3"},{"k":"text","la":"Dóminus cónterens bella: Dóminus nomen est illi."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 9:1-6"},{"k":"text","la":"In illo témpore: Convocátis Jesus duódecim Apóstolis, dedit illis virtútem et potestátem super ómnia dæmónia, et ut languóres curárent. Et misit illos prædicáre regnum Dei et sanáre infírmos. Et ait ad illos: Nihil tuléritis in via, neque virgam, neque peram, neque panem, neque pecúniam, neque duas túnicas habeátis. Et in quamcúmque domum intravéritis, ibi manéte et inde ne exeátis. Et quicúmque non recéperint vos: exeúntes de civitáte illa, étiam púlverem pedum vestrórum excútite in testimónium supra illos. Egréssi autem circuíbant per castélla, evangelizántes et curántes ubíque."}],"Offertorium":[{"k":"ref","la":"Eccli 46:6"},{"k":"text","la":"Invocávit Altíssimum poténtem in oppugnándo inimícos úndique, et audívit illum magnus et sanctus Deus."}],"Secreta":[{"k":"text","la":"Sacrifícium, Dómine, quod immolámus, placátus inténde: ut, intercedénte beáto Joánne Confessóre tuo, ad conteréndas inimicórum insídias nos in tuæ protectiónis securitáte constítuat."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Sap 10:20"},{"k":"text","la":"Decantavérunt, Dómine, nomen sanctum tuum, et victrícem manum tuam laudavérunt."}],"Postcommunio":[{"k":"text","la":"Repléti alimónia cœlésti et spirituáli pópulo recreáti, quǽsumus, omnípotens Deus: ut, intercedénte beáto Joánne Confessóre tuo, nos ab hoste malígno deféndas, et Ecclésiam tuam perpétua pace custódias."},{"k":"macro","name":"Per Dominum"}]},"hr":{"7fe007b880eff734":{"t":"<i>Pomolimo se</i>.\nBože, koji si po blaženom Ivanu učinio da tvoji vjernici snagom presvetog imena Isusovog nadjačaju neprijatelje Križa, podaj, molimo, da po njegovom zagovoru savladamo zasjede duhovnih neprijatelja i zavrijedimo od tebe primiti vijenac pravednosti.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.\n[preveo M.B.; po uredbi iz 1967. nisu u korizmi dozvoljeni spomeni, pa su molitve za ovaj dan ispuštene iz Radićevog prijevoda Misala.]","kn":"Bože koji si sv. Ivanu dao, da Tvoji vjernici krepošču presvetoga Imena Isusova slave pobjedu nad neprijateljem križa, podaj, molimo, da njegovim zagovorom nadvladamo nasrtaje duhovnih neprijatelja i zaslužimo dostignuti vijenac pravednosti, po istom G. n.","knRef":"Kniewald 1942, str. 538–539 (snimka 270) (OCR)"},"7949546bcdf8fed9":{"t":"Milostivo pogledaj, Gospodine, na žrtvu koju ti prinosimo, da se, po zagovoru blaženog Ivana, tvoga priznavaoca, razbiju zasjede neprijatelja i da budemo postavljeni u sigurnost tvoje zaštite.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.\n[preveo M.B.; po uredbi iz 1967. nisu u korizmi dozvoljeni spomeni, pa su molitve za ovaj dan ispuštene iz Radićevog prijevoda Misala.]","kn":"Primi, Gospodine, umilostivljen žrtvu sto je prinosimo, da nas po zagovoru Tvoga priznavaoca Ivana obezbjedi u Tvojoj zaštiti, satremo nasrtaje neprijatelja; po G. n.","knRef":"Kniewald 1942, str. 538–539 (snimka 270) (OCR)"},"56c098e36b5f293d":{"t":"<i>Pomolimo se</i>.\nOkrijepljeni nebeskom hranom i osvježeni duhovnim kaležom, molimo, svemogući Bože, da nas po zagovoru blaženog Ivana, tvoga priznavaoca, braniš od zlog neprijatelja i Crkvu svoju čuvaš vječnim mirom.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.\n[preveo M.B.; po uredbi iz 1967. nisu u korizmi dozvoljeni spomeni, pa su molitve za ovaj dan ispuštene iz Radićevog prijevoda Misala.]","kn":"popričesna. Molimo, svemogući Bože, da; nas zagovorom blaženog Kajetaina, priznavaoca Tvoga, ova sveta hrana, što je primismo, brani od svih •suprotivština, po G. n.","knRef":"Kniewald 1942, str. 670–671 (snimka 336) (OCR)"}}});
